const prepareBrief = function prepareBrief(input) {
  const escape = (v) => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fields = {
    product: ['Product name', 2, 80],
    appearance: ['Product appearance', 10, 500],
    audience: ['Audience', 3, 180],
    benefit: ['Approved benefit', 5, 350],
    context: ['Scene and intended use', 10, 500],
    cta: ['Call to action', 3, 120],
    restrictions: ['Things to avoid', 0, 500],
  };
  const data = {}, errors = [];
  for (const [key, [label, min, max]] of Object.entries(fields)) {
    const raw = input[key] ?? input[label] ?? '';
    if (typeof raw !== 'string') { errors.push(`${label}: enter text.`); data[key] = ''; continue; }
    const value = raw.normalize('NFC').trim().replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '');
    data[key] = value;
    if (value.length < min || value.length > max) errors.push(`${label}: use ${min}–${max} characters.`);
  }
  const platforms = {'Vertical social (9:16)':'9:16','Landscape video (16:9)':'16:9','Square feed (1:1)':'1:1'};
  const styles = {'Clean studio':'a clean studio setting with soft, even lighting','Everyday lifestyle':'a believable everyday setting with natural light','Bold editorial':'a graphic editorial setting with strong light and simple shapes'};
  data.platform = input.platform ?? input['Video format'];
  data.style = input.style ?? input['Visual style'];
  const rawDuration = input.duration ?? input['Planned edit length'];
  const duration = Number(String(rawDuration ?? '').replace(/ seconds$/, ''));
  if (!Object.hasOwn(platforms, data.platform ?? '')) errors.push('Choose one of the three video formats.');
  if (!Object.hasOwn(styles, data.style ?? '')) errors.push('Choose one of the three visual styles.');
  if (![15, 20, 30].includes(duration)) errors.push('Choose a planned edit length of 15, 20 or 30 seconds.');
  if (errors.length) return {valid:false, errors, errorHtml:`<h2>Please revise the brief</h2><ul>${errors.map(e=>`<li>${escape(e)}</li>`).join('')}</ul><p>Open the original brief form in a new tab and resubmit. No request was sent to Cicadas and no video was generated.</p>`};
  data.duration = duration; data.ratio = platforms[data.platform];
  const cuts = [Math.round(duration * .25), Math.round(duration * .5)]; cuts.push(duration - cuts[0] - cuts[1]);
  const shared = `Product description supplied by the user: ${data.appearance}\nSetting and use supplied by the user: ${data.context}\nVisual direction: ${styles[data.style]}. Compose for ${data.ratio}.\nKeep the product's described color, shape and materials consistent. One simple camera movement. No generated captions, logo lettering, invented performance demonstrations, or before-and-after claims. Add any required text during editing.${data.restrictions ? `\nUser restrictions: ${data.restrictions}` : ''}`;
  const shots = [
    {role:'Hook',action:'Open with a medium-wide view that introduces the product in the supplied setting. Keep the main subject clear and the background uncluttered.',editorNote:`Introduce the context for ${data.audience}; do not add unsupported facts.`},
    {role:'Product detail',action:'Show a steady close view of the product and the visible details described by the user. Use a slow, restrained push-in. Do not infer hidden features or physical performance.',editorNote:`Review this user-supplied benefit before using it as an editing caption: ${data.benefit}`},
    {role:'Closing frame',action:'End on a clean hero view of the product with empty space for a call-to-action added later by the editor. Hold the composition steady.',editorNote:`Add this user-supplied call to action during editing: ${data.cta}`},
  ].map((s,i)=>({...s,number:i+1,editSeconds:cuts[i],prompt:`Shot ${i+1} — ${s.role}\n${s.action}\n${shared}`}));
  const markdown = `# ${data.product} — video handoff pack\n\nPrepared from your inputs using fixed planning rules; no AI model was called.\n\nAudience: ${data.audience}\nFormat: ${data.platform}\nPlanned final edit: ${duration} seconds\nApproved benefit (supplied by you, not independently verified): ${data.benefit}\nCall to action: ${data.cta}\n\n${shots.map(s=>`## ${s.number}. ${s.role} — planned edit ${s.editSeconds}s\n\n${s.prompt}\n\nEditing note: ${s.editorNote}`).join('\n\n')}\n\n## Manual generation\nReview the prompts. Open https://cicadas.ai/ and choose a currently available video tool. Copy one prompt at a time. Check supported aspect ratios, clip lengths, price and account limits before generating. Planned edit timings are not supported model-duration claims. Generate separately and trim/assemble clips in your editor. This workflow does not create, combine, download or upload videos. Text prompts do not guarantee exact brand or product fidelity.\n`;
  const reviewHtml = `<h2>${escape(data.product)} — review your plan</h2><p><strong>${duration}-second planned edit · ${escape(data.ratio)}</strong></p><p>Prepared from your inputs using fixed planning rules. No AI model or Cicadas API has been called.</p><p><strong>Audience:</strong> ${escape(data.audience)}<br><strong>Benefit to verify:</strong> ${escape(data.benefit)}<br><strong>Call to action:</strong> ${escape(data.cta)}</p>${shots.map(s=>`<h3>${s.number}. ${s.role} · ${s.editSeconds}s in the final edit</h3><p>${escape(s.editorNote)}</p><pre>${escape(s.prompt)}</pre>`).join('')}<p><strong>Before approving:</strong> check product facts, visual accuracy, rights to the supplied material and restrictions. These are draft prompts, not generated videos. Timings are editing guidance; check actual model options later.</p>`;
  return {valid:true,brief:data,shots,markdown,reviewHtml};
};
return $input.all().map(item => ({json:prepareBrief(item.json)}));

const renderHandoff = function renderHandoff(plan, decision) {
  const escape = (v) => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const approved = decision === 'Approve the draft and show the manual handoff';
  if (!plan?.valid || !approved) return {approved:false,html:'<h2>Brief needs revision</h2><p>No generation request was sent. Open the original brief form in a new tab, revise your inputs, and resubmit.</p>'};
  const css = 'body{margin:0;background:#f5f3ee;color:#1e2926;font:16px/1.65 system-ui,sans-serif}main{max-width:860px;margin:36px auto;padding:32px;background:#fff;border-radius:16px}h1{font-size:32px;line-height:1.2}h2{font-size:22px}h3{font-size:19px}pre,textarea{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 ui-monospace,monospace}textarea{width:100%;box-sizing:border-box;min-height:230px;padding:16px;border:1px solid #c7ceca;border-radius:8px;background:#f8faf9}a{color:#185c47}.button{display:inline-block;padding:12px 20px;background:#185c47;color:#fff;border-radius:8px;text-decoration:none}section{border-top:1px solid #dfe4df;margin-top:28px;padding-top:20px}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#5d6a60}.notice{background:#fff5dc;padding:16px;border-radius:8px}ul{padding-left:22px}@media(max-width:600px){main{margin:0;padding:22px;border-radius:0}h1{font-size:27px}}@media print{body{background:white}main{margin:0;padding:0}textarea,.button{display:none}pre{display:block!important}}';
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${escape(plan.brief.product)} — video handoff</title><style>${css}</style></head><body><main><p class="eyebrow">Reviewed draft · manual handoff</p><h1>${escape(plan.brief.product)}</h1><p>Your ${plan.brief.duration}-second edit plan is ready. Copy each prompt below and review the output after generation.</p><div class="notice"><strong>No video has been generated and no generation credits have been spent by this workflow.</strong> n8n hosting or execution costs may still apply. Cicadas is a separate service: sign in and check its current pricing and limits before generating.</div><ol><li>Select and copy one shot prompt.</li><li>Open Cicadas, choose an available video tool, and paste the prompt manually.</li><li>Check its available format, clip duration and price before confirming generation.</li><li>Review the clips, then trim, assemble and add text in your own editor.</li></ol><a class="button" href="https://cicadas.ai/" target="_blank" rel="noopener noreferrer">Open Cicadas</a><p>This link does not transfer your brief, fill in a prompt, or start generation. Exact product likeness is not guaranteed by text prompts.</p>${plan.shots.map(s=>`<section><h2>${s.number}. ${s.role}</h2><p>Planned edit: ${s.editSeconds} seconds. ${escape(s.editorNote)}</p><label for="shot-${s.number}">Select and copy this prompt</label><textarea id="shot-${s.number}" readonly>${escape(s.prompt)}</textarea><pre style="display:none">${escape(s.prompt)}</pre></section>`).join('')}<section><h2>Complete handoff pack</h2><p>Copy this Markdown into your project notes. Use your browser’s Print command for a paper/PDF review copy.</p><label for="pack">Full project notes</label><textarea id="pack" readonly>${escape(plan.markdown)}</textarea><ul><li>Facts and restrictions come from the submitted brief; they have not been independently verified.</li><li>The storyboard uses fixed rules, not AI reasoning.</li><li>No API credentials, external calls, video assembly or automatic publishing are included.</li></ul></section></main></body></html>`;
  return {approved:true,html,markdown:plan.markdown};
};
const plan = $('Prepare and validate brief').first().json;
return [{json:renderHandoff(plan,$input.first().json.decision)}];
